INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Additionsmethode nur für die Fertigung geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Dienstleistungen anwendbar"}, {"text": "Ja", "correct": false, "because": "Nicht branchenspezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der Additionsmethode?', 3, '[{"text": "Kostenaufsummierung", "correct": true, "because": "Ermittelt Gesamtkosten"}, {"text": "Umsatzprognose", "correct": false, "because": "Nicht primär"}, {"text": "Mitarbeiterplanung", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kostenarten summiere ich bei der Additionsmethode?', 5, '[{"text": "Materialkosten", "correct": true, "because": "Direkte Kosten"}, {"text": "Personalkosten", "correct": true, "because": "Wichtiger Bestandteil"}, {"text": "Marketingkosten", "correct": false, "because": "Oft separat"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Additionsmethode addiert Einzelkosten. b) Sie ignoriert Gemeinkosten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gemeinkosten können einbezogen werden"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Additionsmethode?', 4, '[{"text": "Direkte Kosten", "correct": false, "because": "Kern der Methode"}, {"text": "Indirekte Kosten", "correct": false, "because": "Können einbezogen werden"}, {"text": "Firmenlogo", "correct": true, "because": "Irrelevant für Kosten"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Additionsmethode Gemeinkosten ausschließt?', 2, '[{"text": "Nein", "correct": true, "because": "Kann sie einbeziehen"}, {"text": "Ja", "correct": false, "because": "Flexibel anpassbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kostenart ist bei der Additionsmethode primär?', 3, '[{"text": "Einzelkosten", "correct": true, "because": "Direkt zurechenbar"}, {"text": "Fixkosten", "correct": false, "because": "Sekundär"}, {"text": "Variable Kosten", "correct": false, "because": "Teilweise enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Anwendung der Additionsmethode?', 5, '[{"text": "Summierung der Kosten", "correct": true, "because": "Kernprozess"}, {"text": "Kostenstellenrechnung", "correct": true, "because": "Für Gemeinkosten"}, {"text": "Umsatzanalyse", "correct": false, "because": "Nicht Teil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Die Additionsmethode ist einfach. b) Sie ist nur für Großunternehmen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch für kleine Firmen geeignet"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Additionsmethode unwichtig?', 4, '[{"text": "Kostenaufschlüsselung", "correct": false, "because": "Basis der Methode"}, {"text": "Kostenarten", "correct": false, "because": "Wichtig für Summierung"}, {"text": "Mitarbeiteranzahl", "correct": true, "because": "Kein direkter Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Additionsmethode eine Vollkostenrechnung?', 2, '[{"text": "Ja", "correct": true, "because": "Berücksichtigt alle Kosten"}, {"text": "Nein", "correct": false, "because": "Nicht auf Teilkosten beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Additionsmethode?', 4, '[{"text": "Einfache Anwendung", "correct": true, "because": "Klar strukturiert"}, {"text": "Genaue Kostenzuordnung", "correct": true, "because": "Summiert präzise"}, {"text": "Schnelle Umsatzsteigerung", "correct": false, "because": "Kein direkter Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Additionsmethode veraltet ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Immer noch praktikabel"}, {"text": "Ja", "correct": false, "because": "Nicht überholt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Additionsmethode?', 3, '[{"text": "Kostenidentifikation", "correct": true, "because": "Basis der Summierung"}, {"text": "Schnelligkeit", "correct": false, "because": "Genauigkeit wichtiger"}, {"text": "Prognosen", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Additionsmethode summiert Kosten schrittweise. b) Sie ersetzt die Prozesskostenrechnung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Prozesskostenrechnung ist anders"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat die Additionsmethode?', 5, '[{"text": "Einfachheit kann ungenau sein", "correct": true, "because": "Details fehlen manchmal"}, {"text": "Schwer bei komplexen Prozessen", "correct": true, "because": "Weniger detailliert"}, {"text": "Schnelle Anwendung", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Additionsmethode unwichtig?', 3, '[{"text": "Kostenarten", "correct": false, "because": "Kern der Methode"}, {"text": "Summierung", "correct": false, "because": "Hauptprozess"}, {"text": "Markttrends", "correct": true, "because": "Kein Kostenfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann die Additionsmethode Gemeinkosten verteilen?', 3, '[{"text": "Ja", "correct": true, "because": "Mit Zuschlägen möglich"}, {"text": "Nein", "correct": false, "because": "Nicht ausgeschlossen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Additionsmethode für kleine Firmen passt?', 2, '[{"text": "Ja", "correct": true, "because": "Einfach und flexibel"}, {"text": "Nein", "correct": false, "because": "Nicht größenabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich für eine einfache Kostenrechnung?', 4, '[{"text": "Additionsmethode", "correct": true, "because": "Summiert direkt"}, {"text": "Prozesskostenrechnung", "correct": false, "because": "Komplexer"}, {"text": "Deckungsbeitragsrechnung", "correct": false, "because": "Anderer Fokus"}]');
